window.WORD_AI_EXAMPLE_CHUNK = {"entries":{"devil":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"魔鬼"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"折磨"}],"examples":[{"sentence":"In the folktale, the devil offers the farmer a bargain whose hidden cost becomes clear only at the end.","translation":"在民间故事中，魔鬼向农夫提出一项交易，其隐藏代价直到结尾才变得清楚。","targetForm":"devil","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The playwright used the devil as a symbol of temptation rather than as a simple source of fear.","translation":"剧作家把魔鬼用作诱惑的象征，而不是简单的恐惧来源。","targetForm":"devil","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Small administrative delays can devil applicants who have already waited months for a decision.","translation":"小小的行政延误会折磨那些已等待数月决定的申请者。","targetForm":"devil","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Unresolved doubts devilled the committee, even after the main financial questions had been answered.","translation":"即使主要财务问题已经得到回答，未解决的疑虑仍持续困扰着委员会。","targetForm":"devilled","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The novel suggests that the real devils are not mythical creatures, but ordinary habits that weaken judgement.","translation":"小说暗示真正的恶魔并非神话生物，而是削弱判断力的日常习惯。","targetForm":"devils","senseId":"source-n-1","sourceSenseId":"n-1"}]},"defect":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"缺陷","contextReviewed":true},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"缺损","contextReviewed":true}],"examples":[{"sentence":"The inspection found a defect in the protective cover, so the equipment was removed before anyone could use it.","translation":"检查发现防护罩存在缺陷，因此设备在任何人使用前被移走。","targetForm":"defect","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Although the design was attractive, a small defect in the handle made the container difficult to open safely.","translation":"尽管设计美观，手柄上的小缺陷仍使容器难以安全打开。","targetForm":"defect","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Because the defect appeared only under heavy use, the engineers repeated the test with more demanding conditions.","translation":"由于该缺陷只在高强度使用下出现，工程师用更严苛条件重复了测试。","targetForm":"defect","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The medical model illustrated a structural defect without identifying any individual patient or offering treatment advice.","translation":"医学模型展示了一种结构性缺损，没有识别任何具体患者，也未提供治疗建议。","targetForm":"defect","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Before publication, the editor corrected a defect in the chart that had made two categories appear identical.","translation":"发表前，编辑修正了图表中的缺陷；该缺陷曾使两个类别看起来相同。","targetForm":"defect","senseId":"source-n-3","sourceSenseId":"n-3"}]},"deputy":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"副手"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"代理人"}],"examples":[{"sentence":"The deputy director assumed full responsibility while the director was on medical leave.","translation":"副主任在主任休病假期间承担了全部责任。","targetForm":"deputy","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"She appointed her most trusted colleague as her deputy to oversee the daily operations.","translation":"她任命自己最信任的同事为副手，负责监督日常运营。","targetForm":"deputy","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The sheriff's deputy patrolled the rural areas to ensure compliance with the new regulations.","translation":"警长的副手在乡村地区巡逻，确保新规定得到遵守。","targetForm":"deputy","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"During the negotiations, the ambassador acted as a deputy for the foreign minister.","translation":"在谈判期间，大使担任了外交部长的代理人。","targetForm":"deputy","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The deputy manager presented the quarterly report, highlighting areas that required immediate attention.","translation":"副经理提交了季度报告，强调了需要立即关注的领域。","targetForm":"deputy","senseId":"source-n-1","sourceSenseId":"n-1"}]},"decent":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"得体的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"大方的"}],"examples":[{"sentence":"The candidate gave a decent answer because she addressed the strongest objection instead of avoiding the difficult point.","translation":"这名候选人给出了得体回答，因为她回应了最有力的反对意见，而非回避难点。","targetForm":"decent","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Although the room was small, it offered decent working conditions with enough light, space, and quiet.","translation":"尽管房间很小，它仍提供了相当好的工作条件，有足够的光线、空间和安静环境。","targetForm":"decent","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The organiser asked everyone to dress in decent clothes because the event would include guests from several local schools.","translation":"组织者要求每个人穿着得体，因为活动会有来自多所本地学校的来宾。","targetForm":"decent","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Because the village needed decent housing, the plan included homes that could be maintained at a reasonable cost.","translation":"由于村庄需要体面的住房，该计划包括可以以合理成本维护的住宅。","targetForm":"decent","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The film was not exceptional, but it was decent enough to start a useful discussion about its historical setting.","translation":"这部电影并不卓越，但足够不错，能引出关于其历史背景的有益讨论。","targetForm":"decent","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"detail":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"细节"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"详述"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"选派"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"详细数据","contextReviewed":true}],"examples":[{"sentence":"The report included enough detail for readers to understand how the conclusion had been reached.","translation":"报告包含足够细节，使读者能够理解结论如何得出。","targetForm":"detail","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the proposal was short, it covered every essential detail about cost, timing, and responsibility.","translation":"尽管提案很短，它仍涵盖成本、时间和责任方面的每个关键细节。","targetForm":"detail","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The appendix detailed the sources used in the survey so that another team could verify the results.","translation":"附录详述了调查所用来源，以便另一团队核实结果。","targetForm":"detailed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Before the inspection, the engineer detailed a member of staff to check the electrical records.","translation":"检查前，工程师指派一名员工核查电气记录。","targetForm":"detailed","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The dashboard offered a detail view that allowed users to examine the data behind each summary figure.","translation":"仪表板提供详细数据视图，使用户能查看每个汇总数字背后的数据。","targetForm":"detail","senseId":"source-other-1","sourceSenseId":"other-1"}]},"destructive":{"senseGroups":[{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"有害的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"破坏的"}],"examples":[{"sentence":"With private rewards so markedly different from social returns, it is no surprise that the pursuit of self-interest (greed) led to such socially destructive consequences.","translation":"此外，对于那些真正在做银行被认为应该做的事情即贷款以及评估信用的那些银行的帮助非常之少。","targetForm":"destructive","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The invasive species proved destructive to the native ecosystem, which had evolved without natural predators for centuries.","translation":"这种入侵物种对本地生态系统具有破坏性，该系统几个世纪以来在没有天敌的情况下进化。","targetForm":"destructive","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Because destructive criticism focuses on personal attacks rather than constructive feedback, it rarely leads to improvement.","translation":"由于破坏性的批评侧重于人身攻击而非建设性反馈，它很少能带来改进。","targetForm":"destructive","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"While some insects are beneficial, others have a destructive effect on crops, thereby threatening food security.","translation":"虽然有些昆虫是有益的，但其他昆虫对农作物有破坏性影响，从而威胁粮食安全。","targetForm":"destructive","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Although economic growth is necessary, it can become destructive when it ignores environmental sustainability.","translation":"尽管经济增长是必要的，但当它忽视环境可持续性时，就可能变得具有破坏性。","targetForm":"destructive","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"degree":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"程度"}],"examples":[{"sentence":"All social interactions, naturally, will involve some degree of insincerity, which I believe is necessary.","translation":"所有的社交，自然而然地，都会掺入一些虚伪的成分，我想这是有其必要的。","targetForm":"degree","senseId":"source-n-1","sourceSenseId":"n-1"}]},"dependent":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"依赖他人者"}],"examples":[{"sentence":"A more enlightened approach to shared resources is needed, one less dependent on neo-colonial control.","translation":"我们需要一种更为开明的分享资源的方法，一种更少新殖民主义色彩的方法。","targetForm":"dependent","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In short, no matter what Trump says, Germany will remain dependent on the US nuclear umbrella for the foreseeable future.","translation":"在短期，不管特朗普说什么，在可预见的未来德国都要继续依靠美国核保护伞。","targetForm":"dependent","senseId":"source-n-1","sourceSenseId":"n-1"}]},"deny":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"否认"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"拒绝"}],"examples":[{"sentence":"The manufacturer continued to deny that its software had collected location data without informed consent.","translation":"该制造商仍然否认其软件曾在用户不知情的情况下收集位置数据。","targetForm":"deny","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the figures were independently verified, managers denied that the project's budget had been poorly managed.","translation":"尽管这些数据经过独立核实，管理人员仍否认该项目预算管理不善。","targetForm":"denied","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"No serious historian denies the profound influence of maritime trade on the development of coastal cities.","translation":"严肃的历史学家无不承认海上贸易对沿海城市发展产生了深远影响。","targetForm":"denies","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The bank may deny credit to applicants who conceal substantial debts on their financial statements.","translation":"银行可能拒绝向在财务资料中隐瞒巨额债务的申请人提供信贷。","targetForm":"deny","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Hospital policy denied visitors access to the isolation ward until the infection risk had been reassessed.","translation":"在感染风险得到重新评估之前，医院规定禁止访客进入隔离病房。","targetForm":"denied","senseId":"source-v-2","sourceSenseId":"v-2"}]},"depress":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"使沮丧"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"压低"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"降低"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"使萧条"}],"examples":[{"sentence":"Although the gloomy forecast depressed the volunteers at first, clear instructions soon restored their confidence.","translation":"尽管阴沉的预报起初让志愿者感到沮丧，明确的指令很快恢复了他们的信心。","targetForm":"depressed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because a sudden surplus of fruit depressed prices, growers postponed part of the harvest.","translation":"由于水果突然供过于求压低了价格，种植者推迟采收一部分作物。","targetForm":"depressed","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Persistent uncertainty can depress consumer spending because households delay major purchases.","translation":"持续的不确定性会抑制消费支出，因为家庭会推迟大额购买。","targetForm":"depress","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Excessive screen time may depress academic performance because it reduces the hours available for focused study.","translation":"过度使用屏幕可能会降低学业表现，因为它减少了可用于专注学习的时间。","targetForm":"depress","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Weak demand depressed the local economy until new transport links attracted outside investment.","translation":"需求疲软使当地经济低迷，直到新的交通连接吸引了外来投资。","targetForm":"depressed","senseId":"source-v-4","sourceSenseId":"v-4"}]},"death":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"逝世","contextReviewed":true},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"死亡"}],"examples":[{"sentence":"Although the death of a loved one is deeply painful, shared memories can help a family support one another.","translation":"尽管亲人的离世令人非常痛苦，共同的回忆能帮助家人彼此扶持。","targetForm":"death","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because the death penalty remains controversial, many countries have replaced it with life imprisonment.","translation":"由于死刑仍具争议，许多国家已用无期徒刑取代它。","targetForm":"death","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The medical team examined the cause of death before completing the official report.","translation":"医疗团队在完成正式报告前查明了死亡原因。","targetForm":"death","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When public records show a rise in preventable death, officials must strengthen health services.","translation":"当公共记录显示可预防死亡增加时，官员必须加强卫生服务。","targetForm":"death","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The novel treats death not as a spectacle, but as a moment that changes every surviving character.","translation":"这部小说并未把死亡当作噱头，而是把它写成改变每个幸存角色的时刻。","targetForm":"death","senseId":"source-n-1","sourceSenseId":"n-1"}]},"descent":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"下降；下行"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"家系；出身"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"侵袭；突然来临"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"血统；世系"}],"examples":[{"sentence":"Although the pilot initiated a controlled descent, the sudden loss of cabin pressure forced an emergency landing.","translation":"尽管飞行员启动了受控下降，但机舱压力的突然丧失迫使飞机紧急着陆。","targetForm":"descent","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The mountaineers began their descent at dawn, using ropes to navigate the icy slope that had become dangerously slick overnight.","translation":"登山者在黎明时分开始下撤，利用绳索穿越因一夜之间变得异常光滑而危险的冰坡。","targetForm":"descent","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because she could trace her descent from a long line of scholars, she felt a deep responsibility to pursue academic excellence.","translation":"因为她能追溯到自己出身于一个学者世家，她深感有责任追求学术卓越。","targetForm":"descent","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The unexpected descent of a violent storm disrupted the outdoor ceremony, which had to be moved indoors at the last minute.","translation":"一场猛烈风暴的突然侵袭打乱了户外仪式，仪式不得不在最后一刻移至室内。","targetForm":"descent","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"While researching his family history, he discovered a fascinating descent from a medieval knight, which inspired him to write a novel.","translation":"在研究家族史时，他发现了一位中世纪骑士的迷人血统，这激发了他写一部小说。","targetForm":"descent","senseId":"source-n-4","sourceSenseId":"n-4"}]},"dense":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"密集的"}],"examples":[{"sentence":"Because the forest is so dense that little sunlight reaches the ground, few plants grow beneath the canopy.","translation":"由于森林十分茂密，几乎没有阳光照到地面，树冠下很少有植物生长。","targetForm":"dense","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The textbook's dense prose is rich in detail, but it can overwhelm students who are new to the subject.","translation":"这本教材的文字密集而细节丰富，但可能使刚接触该学科的学生不堪重负。","targetForm":"dense","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Urban planners must address the pressures created by dense populations if they are to build sustainable cities.","translation":"城市规划者必须应对人口密集带来的压力，才能建设可持续城市。","targetForm":"dense","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the regulations were designed to improve safety, their dense wording sometimes discouraged small firms from innovating.","translation":"尽管这些法规旨在提高安全性，其密集晦涩的措辞有时会阻碍小企业创新。","targetForm":"dense","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The dense network of community ties spread information and practical support quickly during the emergency.","translation":"社区中密集的人际关系网络在紧急情况下迅速传播信息和实际支持。","targetForm":"dense","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"democracy":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"民主政治"}],"examples":[{"sentence":"The key question, however, is how much impact change at the top will have on South Africa’s troubled democracy.","translation":"但关键的问题是顶层的变化能够在多大程度上影响到困难重重的南非民主。","targetForm":"democracy","senseId":"source-n-1","sourceSenseId":"n-1"}]},"dead":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"死的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"不活泼的"},{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"熄灭的"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"死者"},{"id":"source-adv-1","partOfSpeech":"adv.","sourceSenseIds":["adv-1"],"sense":"完全地"}],"examples":[{"sentence":"Although the tree looked dead after winter, new buds appeared once the weather became warmer.","translation":"尽管这棵树冬天后看似枯死，天气转暖后仍长出了新芽。","targetForm":"dead","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The discussion became dead when nobody was willing to question the weak proposal.","translation":"当没有人愿意质疑那份薄弱的提案时，讨论变得毫无生气。","targetForm":"dead","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"If the battery is dead, the device will not respond until it is charged or replaced.","translation":"如果电池没电，设备在充电或更换前不会响应。","targetForm":"dead","senseId":"source-adj-4","sourceSenseId":"adj-4"},{"sentence":"The memorial asked visitors to remember the dead while supporting families affected by the disaster.","translation":"纪念活动请来访者缅怀死者，同时支持受灾家庭。","targetForm":"dead","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The train stopped dead when a signal failed, causing passengers to wait on the platform.","translation":"信号故障时，列车完全停住，乘客只得在站台上等待。","targetForm":"dead","senseId":"source-adv-1","sourceSenseId":"adv-1"}]},"desire":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"欲望"}],"examples":[{"sentence":"And yet, despite the hardship the sanctions will cause for ordinary Iranians, they are unlikely to deliver the outcomes that US President Donald Trump desires.","translation":"但尽管这些制裁会令伊朗民众的生活变得艰难，但却不太可能实现美国总统特朗普所寄望的结果。","targetForm":"desires","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The desire for innovation, when combined with adequate funding, can lead to breakthroughs that transform entire industries.","translation":"当创新的渴望与充足的资金相结合时，可以带来突破，从而改变整个行业。","targetForm":"desire","senseId":"source-n-1","sourceSenseId":"n-1"}]},"definite":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"明确的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"一定的"},{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"确切的","contextReviewed":true}],"examples":[{"sentence":"The committee reached a definite conclusion after reviewing all the evidence presented during the hearing.","translation":"委员会在审查了听证会上提交的所有证据后，得出了明确的结论。","targetForm":"definite","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"There is a definite correlation between regular exercise and improved mental health, as numerous studies have shown.","translation":"正如众多研究所表明的，定期锻炼与改善心理健康之间存在一定的关联。","targetForm":"definite","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The contract requires a definite timeline for project completion, leaving no room for ambiguity.","translation":"合同要求项目完成有确切的时间表，不容有任何含糊之处。","targetForm":"definite","senseId":"source-adj-4","sourceSenseId":"adj-4"},{"sentence":"Her promotion was a definite sign that the company valued her contributions to the team.","translation":"她的晋升是一个明确的信号，表明公司重视她对团队的贡献。","targetForm":"definite","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The scientist provided a definite explanation for the phenomenon, based on rigorous experimental data.","translation":"科学家根据严格的实验数据，对这一现象提供了确切的解释。","targetForm":"definite","senseId":"source-adj-4","sourceSenseId":"adj-4"}]},"determine":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"决定"}],"examples":[{"sentence":"How we answer these questions will in large part determine whether, in a relentlessly globalizing world, fear has the last word.","translation":"我们对这些问题的答案将在很大程度上决定，在这个残酷地全球化的世界中，恐惧是否是最后的特征。","targetForm":"determine","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The next few years may well determine if our shared dream of ridding the world of nuclear weapons will ever be realized.","translation":"未来几年将决定我们让核武器从地球上消失的梦想是否能够实现。","targetForm":"determine","senseId":"source-v-1","sourceSenseId":"v-1"}]},"deviate":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"偏离"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"使偏离"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"脱离常规的"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"脱离常规的人"}],"examples":[{"sentence":"The researcher refused to deviate from the established protocol, ensuring the experiment's reproducibility.","translation":"研究人员拒绝偏离既定方案，确保了实验的可重复性。","targetForm":"deviate","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"When the spacecraft began to deviate from its intended trajectory, engineers quickly initiated corrective maneuvers.","translation":"当航天器开始偏离预定轨道时，工程师迅速启动了修正机动。","targetForm":"deviate","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The project's success depended on not allowing external pressures to deviate the team from its core objectives.","translation":"项目的成功取决于不让外部压力使团队偏离其核心目标。","targetForm":"deviate","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Her deviate approach to problem-solving, though unconventional, yielded remarkably innovative solutions.","translation":"她脱离常规的解决问题方法虽然非常规，却产生了非常创新的解决方案。","targetForm":"deviate","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"In a field that rewards conformity, he was often dismissed as a deviate for his unorthodox theories.","translation":"在一个奖励循规蹈矩的领域，他常因非正统理论而被视为脱离常规的人。","targetForm":"deviate","senseId":"source-n-1","sourceSenseId":"n-1"}]},"desolate":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"荒凉的"}],"examples":[{"sentence":"The desolate former industrial zone now stands as a reminder of decades of economic decline.","translation":"这片荒凉的旧工业区如今成为数十年经济衰退的提醒。","targetForm":"desolate","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Because the remote village became desolate after the earthquake, officials arranged a relocation programme.","translation":"由于偏远村庄在地震后变得荒凉，官员安排了搬迁计划。","targetForm":"desolate","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the desert appears desolate, it supports a distinctive ecosystem adapted to extreme conditions.","translation":"尽管沙漠看似荒凉，它仍支持一个适应极端条件的独特生态系统。","targetForm":"desolate","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The once-busy market square lay desolate, with empty stalls that reflected years of neglect.","translation":"曾经繁忙的市场广场一片荒凉，空摊位反映出多年的忽视。","targetForm":"desolate","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"When the mine closed, it left a desolate terrain whose open pits threatened local water supplies.","translation":"矿场关闭时留下了一片荒凉土地，其露天矿坑威胁当地供水。","targetForm":"desolate","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"deposit":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"存款"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"堆积物"}],"examples":[{"sentence":"For northern Europeans, two prospects raise particular concern: risk sharing (for example, in underwriting retail bank deposits) and a eurozone budget.","translation":"对北欧来说，两个前景引起了特别关注：风险分担（比如兜底零售银行存款）和欧元区预算。","targetForm":"deposits","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The final pitfall is excessively rapid depletion of oil or mineral deposits, in violation of optimal rates of saving, let alone environmental preservation.","translation":"最后一个陷阱是石油矿产资源过早的耗尽，违反节约原则，更说不上保护环境了。","targetForm":"deposits","senseId":"source-n-3","sourceSenseId":"n-3"}]},"describe":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"描述"}],"examples":[{"sentence":"This missing science would describe processes, and how entire systems evolve.","translation":"这种缺失的科学法则是用来描述过程，以及整个系统如何演化。","targetForm":"describe","senseId":"source-v-1","sourceSenseId":"v-1"}]},"dental":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"牙齿的"},{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"齿音","contextReviewed":true},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"齿的","contextReviewed":true}],"examples":[{"sentence":"Regular dental checkups are essential for maintaining overall oral health and preventing serious complications.","translation":"定期进行牙科检查对于维护整体口腔健康和预防严重并发症至关重要。","targetForm":"dental","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The dental hygienist demonstrated the correct brushing technique to the patient during the appointment.","translation":"牙科保健员在预约期间向患者演示了正确的刷牙技巧。","targetForm":"dental","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Advanced dental implants can restore both the function and appearance of missing teeth effectively.","translation":"先进的牙科种植体能够有效恢复缺失牙齿的功能和外观。","targetForm":"dental","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"In phonetics, the English 'th' sounds are classified as dental fricatives because the tongue touches the teeth.","translation":"在语音学中，英语的'th'音被归类为齿擦音，因为舌头接触牙齿。","targetForm":"dental","senseId":"source-adj-4","sourceSenseId":"adj-4"},{"sentence":"The linguist explained that some languages use dental consonants, which are articulated with the tongue against the upper teeth.","translation":"语言学家解释说，一些语言使用齿辅音，这些音是通过舌头抵住上齿发出的。","targetForm":"dental","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"delay":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"耽搁"}],"examples":[{"sentence":"And yet, for all the woe, a resolution remains possible; to achieve it, five steps must be taken without delay.","translation":"但尽管局势如此痛苦，仍然保留着和平解决的生机；要想实现这个目标，必须立即实行五步走政策。","targetForm":"delay","senseId":"source-n-1","sourceSenseId":"n-1"}]},"deem":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"认为"}],"examples":[{"sentence":"The committee deemed the proposal insufficiently rigorous for publication in a peer-reviewed journal.","translation":"委员会认为该提案不够严谨，不适合在同行评审期刊上发表。","targetForm":"deemed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Many scholars deem the discovery a turning point in our understanding of ancient civilizations.","translation":"许多学者认为这一发现是我们理解古代文明的一个转折点。","targetForm":"deem","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The judge deemed it necessary to review the evidence before reaching a final verdict.","translation":"法官认为在做出最终裁决之前有必要审查证据。","targetForm":"deemed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Experts deem the new policy likely to stimulate economic growth without exacerbating inflation.","translation":"专家们认为新政策有可能刺激经济增长而不加剧通货膨胀。","targetForm":"deem","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The board deemed the candidate's extensive experience a decisive factor in the hiring process.","translation":"董事会认为该候选人丰富的经验是招聘过程中的决定性因素。","targetForm":"deemed","senseId":"source-v-1","sourceSenseId":"v-1"}]},"deed":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"行为"}],"examples":[{"sentence":"You scorned both the Nymphs, who beheld your deeds, and me the mighty Pan.","translation":"你蔑视了目睹你罪行的仙女们，也蔑视了我を这位强大的潘神。","targetForm":"deeds","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The depravity of the king's deeds led the people to believe he was nothing more than a tyrant that needed to be overthrown.","translation":"国王的卑劣行为致使人们相信他只是个该被推翻的暴君。","targetForm":"deeds","senseId":"source-n-1","sourceSenseId":"n-1"}]},"defy":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"藐视"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"使落空"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"挑战"}],"examples":[{"sentence":"The young activist decided to defy the unjust law by organizing a peaceful protest in the city square.","translation":"这位年轻的活动家决定通过在市中心广场组织和平抗议来藐视不公正的法律。","targetForm":"defy","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Despite numerous warnings, the rebellious teenager continued to defy his parents' authority at every opportunity.","translation":"尽管多次受到警告，这个叛逆的青少年仍然抓住一切机会挑衅父母的权威。","targetForm":"defy","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The complex mathematical theorem defied all attempts at a simple proof, frustrating researchers for decades.","translation":"这个复杂的数学定理使所有简单证明的尝试都落空了，几十年来一直困扰着研究人员。","targetForm":"defied","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The athlete's remarkable recovery from injury defied medical expectations, allowing her to compete again within months.","translation":"这位运动员从伤病中惊人的康复使医学预期落空，让她在数月内得以再次参赛。","targetForm":"defied","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The climber's solo ascent of the treacherous peak was a direct defy of nature's most formidable obstacles.","translation":"这位登山者独自攀登险峻山峰的行为是对自然最可怕障碍的直接挑战。","targetForm":"defy","senseId":"source-n-1","sourceSenseId":"n-1"}]},"device":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"装置"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"设备"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"计算机设备","contextReviewed":true},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"设计"}],"examples":[{"sentence":"The warning device flashes when river levels rise, giving nearby residents time to prepare safely.","translation":"河流水位上升时，这个预警装置会闪烁，让附近居民有时间安全准备。","targetForm":"device","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the device uses very little power, researchers can leave it in the forest for months.","translation":"由于这台设备耗电极少，研究人员可以把它留在森林中数月。","targetForm":"device","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"When the tablet recognised the new device, the technician checked that its driver was up to date.","translation":"平板电脑识别到新设备后，技术人员检查了它的驱动程序是否为最新版本。","targetForm":"device","senseId":"source-other-1","sourceSenseId":"other-1"},{"sentence":"The writer used a changing season as a device to show how the characters gradually matured.","translation":"作者把季节变化作为一种写作手法，展现人物如何逐渐成熟。","targetForm":"device","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although the device looks simple, its sensor can detect tiny changes in air quality.","translation":"尽管这台设备看起来简单，它的传感器却能检测到空气质量的微小变化。","targetForm":"device","senseId":"source-n-5","sourceSenseId":"n-5"}]},"dessert":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"餐后甜点"}],"examples":[{"sentence":"While eating dessert, our desire to travel to that country grew stronger.","translation":"我们吃甜点的时候，去那个国家旅游的愿望更强烈了。","targetForm":"dessert","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Christmas gingerbread, also called honey cake, is a traditional German dessert.","translation":"圣诞姜饼是一种传统的德国点心。","targetForm":"dessert","senseId":"source-n-1","sourceSenseId":"n-1"}]},"demand":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"要求"}],"examples":[{"sentence":"But absolute demands for self-determination are likely to become a source of endless violence unless handled carefully.","translation":"对当今世界的民族自决要求应该在多边框架内，在评估动机，手段以及有关的后果的基础上，进行个案判断。","targetForm":"demands","senseId":"source-n-1","sourceSenseId":"n-1"}]},"defeat":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"败北"}],"examples":[{"sentence":"Britain’s pro-European progressive forces could still snatch victory from the jaws of defeat for three related reasons.","translation":"英国的亲欧进步力量仍有可能出奇制胜，有三个互相关联的原因。","targetForm":"defeat","senseId":"source-n-1","sourceSenseId":"n-1"}]},"designate":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"指定"}],"examples":[{"sentence":"Although the CEO will designate a successor next month, the transition plan remains confidential to ensure stability.","translation":"尽管首席执行官将于下个月指定一位继任者，但过渡计划仍属机密以确保稳定。","targetForm":"designate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"In many countries, laws designate certain areas as protected zones to preserve biodiversity, thereby safeguarding endangered species.","translation":"在许多国家，法律将某些区域指定为保护区以维护生物多样性，从而保护濒危物种。","targetForm":"designate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The new policy will designate English as the primary language for all official documents, which may improve international communication.","translation":"新政策将指定英语为所有官方文件的主要语言，这可能会改善国际交流。","targetForm":"designate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The professor asked the students to designate one group member to present their findings, because effective collaboration requires clear roles.","translation":"教授要求学生们指定一名小组成员来展示他们的研究结果，因为有效的合作需要明确的角色。","targetForm":"designate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The committee decided to designate a portion of the budget for renewable energy research, which will accelerate the transition to clean power.","translation":"委员会决定指定一部分预算用于可再生能源研究，这将加速向清洁能源的过渡。","targetForm":"designate","senseId":"source-v-1","sourceSenseId":"v-1"}]},"depth":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"深度"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"深处"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"深奥"}],"examples":[{"sentence":"Because the foundation lacked sufficient depth, the building developed cracks after the ground shifted during the earthquake.","translation":"由于地基深度不足，地震时地面发生位移后，这栋建筑出现了裂缝。","targetForm":"depth","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"At a depth of thirty metres, divers found that the water was colder and the visibility had almost disappeared.","translation":"在三十米深处，潜水员发现水温更低，能见度也几乎消失。","targetForm":"depth","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In the depths of winter, the village can be reached only by a narrow road that is often blocked by snow.","translation":"在隆冬时节，通往村庄的只有一条狭窄道路，而且常被积雪阻断。","targetForm":"depths","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The depth of the analysis made the report persuasive because it combined statistics with carefully chosen interviews.","translation":"这份报告分析深刻，结合了统计数据和精心选取的访谈，因此很有说服力。","targetForm":"depth","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Although the lecture was brief, it conveyed the depth of the philosophical disagreement without oversimplifying either position.","translation":"尽管讲座简短，它仍呈现了这场哲学分歧的深刻程度，没有过分简化任何一方立场。","targetForm":"depth","senseId":"source-n-3","sourceSenseId":"n-3"}]},"deer":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"鹿"}],"examples":[{"sentence":"Because deer lack natural predators in the area, their population has grown rapidly, which threatens local vegetation.","translation":"由于该地区鹿缺乏天敌，它们的数量迅速增长，这威胁到当地的植被。","targetForm":"deer","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although deer are often seen as gentle creatures, their overpopulation can lead to severe ecological imbalances.","translation":"尽管鹿通常被视为温顺的动物，但它们的数量过多会导致严重的生态失衡。","targetForm":"deer","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The conservation program, which focuses on restoring native habitats, has helped stabilize the deer population in the region.","translation":"该保护计划专注于恢复原生栖息地，帮助稳定了该地区的鹿群数量。","targetForm":"deer","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"If hunting regulations are not enforced, the deer population may decline to a level that disrupts the entire food chain.","translation":"如果不执行狩猎法规，鹿的数量可能会下降到破坏整个食物链的水平。","targetForm":"deer","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When the highway was built through the forest, it disrupted the migratory routes of deer, thereby increasing the risk of collisions.","translation":"当高速公路穿过森林修建时，它扰乱了鹿的迁徙路线，从而增加了碰撞的风险。","targetForm":"deer","senseId":"source-n-1","sourceSenseId":"n-1"}]},"demonstrate":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"证明"}],"examples":[{"sentence":"And that is what we are doing, as action on three issues of historic consequence demonstrates.","translation":"正如颇具历史意义的行动所表明的那样，这正是我们行动的目标。","targetForm":"demonstrates","senseId":"source-v-2","sourceSenseId":"v-2"}]},"dentist":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"牙科医生"}],"examples":[{"sentence":"You should go to the dentist and have that tooth pulled out.","translation":"你应该去看牙医，把牙拔掉。","targetForm":"dentist","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"She visits the dentist on a regular basis, so she seldom gets toothaches.","translation":"她定期去看牙医，所以她很少牙痛。","targetForm":"dentist","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"According to dentists, tooth decay is not always caused by sweets.","translation":"根据牙医，蛀牙并不总是甜食所引起的。","targetForm":"dentists","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"She goes to the dentist regularly, so she seldom gets toothache.","translation":"她定期去看牙医，因此很少牙疼。","targetForm":"dentist","senseId":"source-n-1","sourceSenseId":"n-1"}]},"define":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"使明确"}],"examples":[{"sentence":"These three realities – social injustice on an unprecedented scale, massive inequities, and a loss of trust in elites – define our political moment, and rightly so.","translation":"这三样现实 — — 前所未有的社会不公、大规模不平等以及对精英失去信任 — — 是当下政坛的特色，确实如此。","targetForm":"define","senseId":"source-v-3","sourceSenseId":"v-3"}]},"desert":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"沙漠"}],"examples":[{"sentence":"When real life friends desert us, books are always ready to offer friendship, sympathy and motivation.","translation":"生活中的朋友弃我们不顾之时，书随时给我们送来友谊、同情和鼓励。","targetForm":"desert","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"She weaves her baskets in the same style as her ancestors who lived in the desert and harvested fruit and vegetables.","translation":"她编织的篮子的样式，与她生活在沙漠中收获水果和蔬​​菜的祖先相同。","targetForm":"desert","senseId":"source-n-1","sourceSenseId":"n-1"}]},"depart":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"背离"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"出发"}],"examples":[{"sentence":"This year’s voting departed markedly from previous National Assembly elections in several other key respects, beyond the support shown for Macron’s new political grouping.","translation":"今年的选举与以往的国民大会选举有着不少关键性的差异，马克龙的新政治集团所赢得的支持只是其中之一。","targetForm":"departed","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The next train arriving at platform 2 will depart for Shibuya at 4:35pm.","translation":"下一班火车将在第二月台, 于下午四点三十五分前往涩谷。","targetForm":"depart","senseId":"source-v-2","sourceSenseId":"v-2"}]},"destiny":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"命运"}],"examples":[{"sentence":"Although some people speak of destiny, the novel suggests that choices still shape a person's future.","translation":"尽管有人谈论命运，这部小说仍表明选择会塑造一个人的未来。","targetForm":"destiny","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The discovery changed the town's destiny because it created new work and attracted skilled residents.","translation":"这项发现改变了小镇的命运，因为它创造了新工作并吸引了有技能的居民。","targetForm":"destiny","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When she met her mentor, she described the encounter as a turning point rather than destiny.","translation":"当她遇到导师时，她把这次相遇描述为转折点，而不是命运。","targetForm":"destiny","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the story questions destiny, readers are invited to consider responsibility alongside chance.","translation":"由于这个故事质疑命运，读者被邀请把责任与机遇一同思考。","targetForm":"destiny","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The play presents destiny as a powerful idea, while allowing its characters to resist it.","translation":"这部戏剧把命运呈现为强大的观念，同时允许角色反抗它。","targetForm":"destiny","senseId":"source-n-1","sourceSenseId":"n-1"}]},"despatch":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"派遣"}],"examples":[{"sentence":"The general ordered his officers to despatch the reconnaissance unit at dawn, thereby gaining a tactical advantage.","translation":"将军命令他的军官们在黎明时派遣侦察部队，从而获得战术优势。","targetForm":"despatch","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because the humanitarian crisis worsened, the United Nations decided to despatch an emergency relief team to the region.","translation":"由于人道主义危机恶化，联合国决定向该地区派遣一支紧急救援队。","targetForm":"despatch","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The editor will despatch a journalist to cover the summit, which is expected to yield significant policy changes.","translation":"编辑将派遣一名记者去报道这次峰会，预计峰会将产生重大的政策变化。","targetForm":"despatch","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the weather was deteriorating, the captain chose to despatch the rescue boat immediately to save the stranded sailors.","translation":"尽管天气正在恶化，船长还是选择立即派出救援船去营救被困的水手。","targetForm":"despatch","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"To ensure the parts arrived on time, the manufacturer had to despatch them via express courier rather than standard mail.","translation":"为确保零件准时到达，制造商不得不通过快递而非普通邮件发送它们。","targetForm":"despatch","senseId":"source-v-1","sourceSenseId":"v-1"}]},"dealer":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"经销商"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"商人"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"交易员","contextReviewed":true}],"examples":[{"sentence":"Before signing the contract, the buyer asked the dealer to provide a written history of the vehicle's maintenance.","translation":"签订合同前，买方要求经销商提供该车辆的书面维修记录。","targetForm":"dealer","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The antique dealer authenticated the cabinet through its joinery, provenance, and the records held by the estate.","translation":"这位古董商通过柜体的榫接工艺、流传记录以及遗产管理方保存的档案鉴定了它的真伪。","targetForm":"dealer","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"A reliable dealer explains the limits of a guarantee rather than making promises that cannot be honoured.","translation":"可靠的经销商会说明保修的限制，而不是作出无法兑现的承诺。","targetForm":"dealer","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"During volatile trading, the currency dealer confirmed the client's instructions before placing the order.","translation":"在交易波动期间，这位外汇交易员在下单前确认了客户的指令。","targetForm":"dealer","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The securities dealer monitored liquidity closely because a large order could move prices in a thin market.","translation":"这位证券交易员密切关注流动性，因为大额订单可能在交易清淡的市场中推动价格变化。","targetForm":"dealer","senseId":"source-n-3","sourceSenseId":"n-3"}]},"deduct":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"扣除"}],"examples":[{"sentence":"The software can automatically deduct bank fees when reconciling accounts, which saves accountants considerable time each month.","translation":"该软件在对账时可以自动扣除银行手续费，这每月为会计师节省了大量时间。","targetForm":"deduct","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"When calculating net profit, it is standard practice to deduct all operating expenses, including depreciation and amortization.","translation":"在计算净利润时，标准做法是扣除所有运营费用，包括折旧和摊销。","targetForm":"deduct","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because the tax code allows you to deduct mortgage interest, many homeowners find that itemizing deductions reduces their overall tax liability.","translation":"由于税法允许扣除抵押贷款利息，许多房主发现逐项列出扣除额能减少他们的总体税负。","targetForm":"deduct","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"If you fail to submit the expense report on time, the finance department will deduct the unverified costs from your next reimbursement.","translation":"如果你未能按时提交费用报告，财务部门将从你的下一次报销中扣除未经核实的费用。","targetForm":"deduct","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the contract stipulates a penalty for late delivery, the client may choose to deduct a smaller amount as a gesture of goodwill.","translation":"尽管合同规定了延迟交货的罚金，客户可能选择扣除较小金额以示善意。","targetForm":"deduct","senseId":"source-v-1","sourceSenseId":"v-1"}]},"descend":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"世代相传"}],"examples":[{"sentence":"Some believe that the British Royal Family is directly descended from the line of King David.","translation":"有些人相信英国皇室是大卫王的后裔。","targetForm":"descended","senseId":"source-v-2","sourceSenseId":"v-2"}]},"dedicate":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"献出"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"贡献"}],"examples":[{"sentence":"Although she had a demanding full-time job, she chose to dedicate her weekends to mentoring disadvantaged students.","translation":"尽管她有一份要求苛刻的全职工作，她还是选择将周末用于辅导弱势学生。","targetForm":"dedicate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Governments that dedicate substantial resources to early childhood education often see long-term improvements in social equity.","translation":"将大量资源投入早期儿童教育的政府，往往会看到社会公平方面的长期改善。","targetForm":"dedicate","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Companies that dedicate a portion of their profits to environmental causes can strengthen both their reputation and customer loyalty.","translation":"将部分利润投入环保事业的公司，既能提升声誉，也能增强客户忠诚度。","targetForm":"dedicate","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Many researchers dedicate years to a single project in order to produce findings that can genuinely advance their field.","translation":"许多研究人员将多年时间投入单一项目，以便得出能够真正推动其领域发展的发现。","targetForm":"dedicate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"If more volunteers dedicate their time to community health programs, the overall well-being of the population is likely to improve.","translation":"如果更多志愿者将时间投入社区健康项目，人口的整体福祉很可能会得到改善。","targetForm":"dedicate","senseId":"source-v-1","sourceSenseId":"v-1"}]},"decorate":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"装饰"}],"examples":[{"sentence":"People there decorate their homes with potted flowers to add to the festival atmosphere.","translation":"为了增添节日的气氛 ，那里的人用盆栽装饰他们的家。","targetForm":"decorate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"You can decorate the cocktail with a cherry or a pineapple.","translation":"你可以用一个樱桃或菠萝来装饰这杯鸡尾酒。","targetForm":"decorate","senseId":"source-v-1","sourceSenseId":"v-1"}]},"delete":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"删除"}],"examples":[{"sentence":"I wish I could figure out how to delete my Facebook account.","translation":"我希望我能知道如何删除我的Facebook帐号。","targetForm":"delete","senseId":"source-v-1","sourceSenseId":"v-1"}]},"depict":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"描写"}],"examples":[{"sentence":"I'm not a poet; I couldn't write a single line to depict its beauty.","translation":"我不是诗人，无法用一行文字描绘它的美丽。","targetForm":"depict","senseId":"source-v-2","sourceSenseId":"v-2"}]},"decade":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"十年"}],"examples":[{"sentence":"But the alternative could be worse: a populist backlash that destroys much of what Mexico has achieved over the last two decades.","translation":"但另一种局面或许更为可怕：任由民粹主义回归摧毁20年来墨西哥所取得的一切成就。","targetForm":"decades","senseId":"source-n-1","sourceSenseId":"n-1"}]},"december":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"十二月"}],"examples":[{"sentence":"In December, the library hosts a quiet exhibition of work created by local school pupils.","translation":"十二月，图书馆举办由当地学生创作的安静主题展览。","targetForm":"December","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although December is often busy, the team reserved two afternoons to review the year's unanswered questions.","translation":"尽管十二月通常很忙，团队仍预留了两个下午回顾这一年尚未回答的问题。","targetForm":"December","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The conference programme will be published in December so that participants can arrange travel well in advance.","translation":"会议日程将于十二月发布，以便参与者能提前安排出行。","targetForm":"December","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"By December, the garden had entered a quieter season, but the volunteers were already planning spring planting.","translation":"到十二月，花园进入较安静的季节，但志愿者已经在规划春季种植。","targetForm":"December","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the deadline falls in December, applicants should request reference letters before the autumn term becomes crowded.","translation":"由于截止日期在十二月，申请者应在秋季学期忙碌前请求推荐信。","targetForm":"December","senseId":"source-n-1","sourceSenseId":"n-1"}]},"deliberate":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"深思熟虑的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"故意的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"从容的"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"仔细考虑"}],"examples":[{"sentence":"The council adopted a deliberate approach, gathering local evidence before committing funds to a permanent redesign.","translation":"委员会采取深思熟虑的方法，在投入永久改造资金前收集本地证据。","targetForm":"deliberate","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the mistake caused inconvenience, the inquiry found no deliberate attempt to conceal information from the public.","translation":"尽管错误造成不便，调查发现没有故意向公众隐瞒信息的企图。","targetForm":"deliberate","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Her deliberate pace during the presentation allowed listeners to absorb the complex comparison without relying on the slides alone.","translation":"她从容的演讲节奏让听众无需只依赖幻灯片也能理解复杂比较。","targetForm":"deliberate","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Before deciding, the panel deliberated on whether the short-term savings would justify reducing access to local services.","translation":"作出决定前，评审组仔细考虑短期节约是否足以证明减少地方服务是合理的。","targetForm":"deliberated","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The authors made a deliberate choice to separate evidence from interpretation, so that readers could judge each claim's strength.","translation":"作者有意选择将证据与解释分开，使读者能判断每项主张的力度。","targetForm":"deliberate","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"devise":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"设计"}],"examples":[{"sentence":"Meanwhile, the administration has deployed thousands of US troops to Afghanistan, but without bothering to devise a political strategy to break the stalemate there.","translation":"此外，政府已经向阿富汗部署了数千名美军，但却没有制定政治策略来打破那里的僵局。","targetForm":"devise","senseId":"source-v-1","sourceSenseId":"v-1"}]},"department":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"部门"}],"examples":[{"sentence":"The objectives of the marketing department and the sales department are not necessarily the same.","translation":"销售部门和营销部门的目标不见得一样。","targetForm":"department","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"First off, I'd like you to come with me to a department store sale.","translation":"首先，我要你跟我一起去百货公司的特价活动。","targetForm":"department","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"For the sake of long-term interests, we have decided to sell the development department.","translation":"为了长期利益，我们决定把开发部门卖掉。","targetForm":"department","senseId":"source-n-1","sourceSenseId":"n-1"}]},"deceive":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"欺骗"}],"examples":[{"sentence":"A polished image can deceive viewers if it removes the context needed to understand what actually happened.","translation":"如果修饰过的图像删去了理解事实所需的背景，它就可能欺骗观看者。","targetForm":"deceive","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the headline was dramatic, it did not deceive readers who checked the original report before sharing it.","translation":"尽管标题很夸张，它并没有欺骗那些在转发前核查原始报告的读者。","targetForm":"deceive","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The museum label explained how perspective can deceive the eye when an object is viewed from a particular angle.","translation":"博物馆标签解释了，当物体从特定角度观看时，透视如何欺骗眼睛。","targetForm":"deceive","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because the seller did not deceive the buyer about the item's condition, the exchange remained straightforward and fair.","translation":"由于卖方没有就物品状况欺骗买方，这次交易保持了直接和公平。","targetForm":"deceive","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Writers should not deceive readers by presenting an opinion as though it were an established fact.","translation":"作者不应把观点说成既定事实，以此欺骗读者。","targetForm":"deceive","senseId":"source-v-1","sourceSenseId":"v-1"}]},"destroy":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"破坏"}],"examples":[{"sentence":"But the alternative could be worse: a populist backlash that destroys much of what Mexico has achieved over the last two decades.","translation":"但另一种局面或许更为可怕：任由民粹主义回归摧毁20年来墨西哥所取得的一切成就。","targetForm":"destroys","senseId":"source-v-1","sourceSenseId":"v-1"}]},"departure":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"离开"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"出发"}],"examples":[{"sentence":"Departure is a partial death but death in essence is not only departure.","translation":"离开是部分的死亡，而死亡不仅仅是离开。","targetForm":"departure","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In China, you have to go to the departure station and buy train tickets there.","translation":"在中国，人人必须去出发的火车站买车票。","targetForm":"departure","senseId":"source-n-2","sourceSenseId":"n-2"}]},"debate":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"讨论"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"辩论"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"辩论"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"争论"}],"examples":[{"sentence":"The debate over housing policy became more constructive when residents were invited to examine the same evidence.","translation":"当居民获邀审视同一份证据后，围绕住房政策的讨论变得更具建设性。","targetForm":"debate","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although the debate was lively, the chair required speakers to answer the strongest opposing argument fairly.","translation":"尽管辩论热烈，主席要求发言者公正回应最有力的反方论点。","targetForm":"debate","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The class held a formal debate so that students could practise supporting claims with reliable sources.","translation":"班级举行正式辩论，以便学生练习用可靠来源支持自己的主张。","targetForm":"debate","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Before approving the plan, the council debated whether its short-term savings would create greater costs later.","translation":"批准该计划前，市议会辩论了它的短期节省是否会在日后造成更大成本。","targetForm":"debated","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Researchers continue to debate how far technology should shape public decisions that affect vulnerable communities.","translation":"研究人员仍在争论技术应在多大程度上影响关乎弱势社区的公共决策。","targetForm":"debate","senseId":"source-v-1","sourceSenseId":"v-1"}]},"devote":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"投入于"}],"examples":[{"sentence":"Because people in the world don't speak the same language, much effort is now devoted to translation.","translation":"因为世界上的人不是讲同一种语言, 所以现在很多人努力致力于翻译。","targetForm":"devoted","senseId":"source-v-1","sourceSenseId":"v-1"}]},"deduce":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"推论"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"演绎出"}],"examples":[{"sentence":"From the pattern of wear on the stones, archaeologists could deduce how people had moved through the ancient entrance.","translation":"考古学家可以从石头的磨损模式推断人们如何穿过古老入口。","targetForm":"deduce","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the message was incomplete, the editor deduced its likely meaning by comparing it with earlier letters.","translation":"尽管信息不完整，编辑仍通过与早期信件对比推断出其可能含义。","targetForm":"deduced","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Students were asked to deduce the rule from several examples rather than being given the answer directly.","translation":"学生被要求从几个例子中推导规则，而不是被直接告知答案。","targetForm":"deduce","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Because the records were carefully dated, researchers could deduce which changes occurred before the policy was introduced.","translation":"由于记录标注了准确日期，研究人员可以推断哪些变化发生在政策出台之前。","targetForm":"deduce","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The engineer deduced that the fault lay in the cable after testing each component of the system separately.","translation":"工程师逐一测试系统部件后，推断故障出在电缆上。","targetForm":"deduced","senseId":"source-v-1","sourceSenseId":"v-1"}]},"destination":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"目的地"}],"examples":[{"sentence":"When you safely arrive at your destination, don't forget to call me.","translation":"你安全到达目的地以后，别忘记打个电话告诉我。","targetForm":"destination","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"We reached our destination just as I thought the car was going to give up the ghost.","translation":"我们抵达目的地的时候，我还以为那辆车快要报废了。","targetForm":"destination","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"My final destination in China is the city of Harbin in the north-east, about one thousand kilometres from Beijing.","translation":"我在中国最后的目的地是东北的哈尔滨，离北京大概一千公里左右。","targetForm":"destination","senseId":"source-n-1","sourceSenseId":"n-1"}]},"debt":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"债务"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"罪过"}],"examples":[{"sentence":"The council published its debt figures so that residents could see how borrowing would affect future spending.","translation":"市议会公布了债务数据，以便居民了解借款会如何影响未来支出。","targetForm":"debt","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the company had debt, it could meet its obligations because its income remained stable during the downturn.","translation":"尽管公司有债务，由于收入在低迷时期保持稳定，它仍能履行义务。","targetForm":"debt","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The report distinguished between short-term debt and investment that would create value over many years.","translation":"报告区分了短期债务与能在多年内创造价值的投资。","targetForm":"debt","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The author acknowledged a debt to earlier scholars whose careful work had made the new study possible.","translation":"作者承认自己亏欠早期学者，因为他们细致的工作使新研究成为可能。","targetForm":"debt","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because the community relied on borrowed funds, it reviewed the debt agreement before beginning the housing project.","translation":"由于社区依赖借入资金，它在开始住房项目之前审查了债务协议。","targetForm":"debt","senseId":"source-n-1","sourceSenseId":"n-1"}]},"dean":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"院长"}],"examples":[{"sentence":"He used to be a professor, but now he is the dean.","translation":"他以前是教授，后来当了系主任。","targetForm":"dean","senseId":"source-n-1","sourceSenseId":"n-1"}]},"declaration":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"宣告"}],"examples":[{"sentence":"For all these reasons, the declaration of a pandemic must not be a prediction but rather a kind of real-time snapshot.","translation":"由于所有这些原因，流行病公告不应是一种预测，而应当是事实情况的反应。","targetForm":"declaration","senseId":"source-n-1","sourceSenseId":"n-1"}]},"denounce":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"抨击"}],"examples":[{"sentence":"The politician pushed for reform by denouncing the corruption of the government officials.","translation":"政治家以揭露政府官员的腐败来推动改革。","targetForm":"denouncing","senseId":"source-v-2","sourceSenseId":"v-2"}]},"delicate":{"senseGroups":[{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"[医] 柔弱的","contextReviewed":true}],"examples":[{"sentence":"Indeed she is young and beautiful, but she is in delicate health.","translation":"她确实年轻貌美，但她体质娇弱。","targetForm":"delicate","senseId":"source-adj-4","sourceSenseId":"adj-4"}]},"definition":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"定义"}],"examples":[{"sentence":"That is basically the definition of resilience: the capacity of a system to absorb disturbance, re-organize, and keep functioning in much the same way as before.","translation":"这就是恢复力的基本定义：系统吸收干扰、重新组织并保持像从前一样运转的能力。","targetForm":"definition","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"To give a definition of a word is more difficult than to give an illustration of its usage.","translation":"要为一个字下定义比为字的用法举例更困难。","targetForm":"definition","senseId":"source-n-1","sourceSenseId":"n-1"}]},"deliver":{"senseGroups":[{"id":"source-v-7","partOfSpeech":"v.","sourceSenseIds":["v-7"],"sense":"交付"}],"examples":[{"sentence":"After years of austerity, infighting, and unemployment, it is time to implement a QE program that delivers what Europe needs.","translation":"在经历了多年的紧缩、暗斗和失业后，是时候实施能满足欧洲需要的量化宽松计划了。","targetForm":"delivers","senseId":"source-v-7","sourceSenseId":"v-7"},{"sentence":"And yet, despite the hardship the sanctions will cause for ordinary Iranians, they are unlikely to deliver the outcomes that US President Donald Trump desires.","translation":"但尽管这些制裁会令伊朗民众的生活变得艰难，但却不太可能实现美国总统特朗普所寄望的结果。","targetForm":"deliver","senseId":"source-v-7","sourceSenseId":"v-7"}]},"deadline":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"最后期限"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"截止期限"}],"examples":[{"sentence":"Even if she wasn't sick, she couldn't complete her doctoral thesis by the deadline because the thesis problem contains a vast amount of detail.","translation":"即使她没生病，到了规定的日期她也完成不了她的博士论文， 因为论文题目涉及的内容太广泛。","targetForm":"deadline","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The red circle on the calendar marking the deadline causes me to fall into anxiety.","translation":"日历上画着红圈的截稿日期使我陷入了焦虑。","targetForm":"deadline","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Wow, I can't believe they actually met the deadline for once.","translation":"哇，真不敢相信他们这次居然真的赶上截止日期了。","targetForm":"deadline","senseId":"source-n-2","sourceSenseId":"n-2"}]},"decision":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"决定"}],"examples":[{"sentence":"Thus, on April 26, 2004, China announced its unilateral decision that Hong Kong is not to have democracy in 2007 without saying when Hong Kong will have it.","translation":"因此，在2004年4月26日，中国宣布了香港不会在2007年实现民主的单方面决定，并且没有说明香港何时实现民主。","targetForm":"decision","senseId":"source-n-1","sourceSenseId":"n-1"}]},"delight":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"愉快"}],"examples":[{"sentence":"It was a fabulous show which brought us an endless delight.","translation":"那是一个给我们带来无穷乐趣的传奇性的演出。","targetForm":"delight","senseId":"source-n-2","sourceSenseId":"n-2"}]},"despite":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"轻视"}],"examples":[{"sentence":"ATHENS – Despite their unequivocal Europeanism, the Irish have been serially mistreated by the European Union.","translation":"发自雅典 — — 尽管有着明确的亲欧倾向，但爱尔兰却一直遭受着欧盟的错误对待。","targetForm":"despite","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Despite all of this, there were compelling reasons to believe that Modi’s government would keep Rajan on board.","translation":"尽管如此，人们仍有充分的理由相信莫迪政府会让拉詹留任。","targetForm":"despite","senseId":"source-n-1","sourceSenseId":"n-1"}]},"deadly":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"致命的"}],"examples":[{"sentence":"So it seems that cloud of odorless deadly gas had a silver lining after all.","translation":"只能说，致命煤气的雾团中，也定会有阳光的。","targetForm":"deadly","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The tip of the spear was dipped in a deadly poison.","translation":"矛尖浸在一种致命的毒药里。","targetForm":"deadly","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"decay":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"衰退"}],"examples":[{"sentence":"The decay of the shrine is due, in part, to acid rain.","translation":"庙宇的毁坏有一部分要归因于酸雨。","targetForm":"decay","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"According to dentists, tooth decay is not always caused by sweets.","translation":"根据牙医，蛀牙并不总是甜食所引起的。","targetForm":"decay","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Many local traditions have fallen into decay in recent years.","translation":"近几年，很多当地的传统都衰败了。","targetForm":"decay","senseId":"source-n-1","sourceSenseId":"n-1"}]},"deaf":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"聋的"}],"examples":[{"sentence":"It requires wisdom to understand wisdom: the music is nothing if the audience is deaf.","translation":"要用智慧来理解智慧：如果听众是聋的话，那音乐什么都不是。","targetForm":"deaf","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Kindness is the language which the deaf can hear and the blind can see.","translation":"善良是聋子能听盲人能看的语言。","targetForm":"deaf","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"There's no one more deaf than he who does not want to listen.","translation":"不愿意聆听的人，才是真正的聋子。","targetForm":"deaf","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"delivery":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"递送"}],"examples":[{"sentence":"If you'd sent the letter by special delivery on Friday, it would've arrived by now.","translation":"如果你周五用特快专递寄出这封信，现在应该已经到了。","targetForm":"delivery","senseId":"source-n-1","sourceSenseId":"n-1"}]},"deserve":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"值得"}],"examples":[{"sentence":"Europe deserves to prove that it is a real community, one diverse, democratic, spiritual, free, and prosperous.","translation":"欧洲应该证明自己是一个真正的社会，一个多元、民主、高尚、自由和繁荣的社会。","targetForm":"deserves","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"It is for this indispensable quality of statesmanship, not only for having helped bring about German reunification, that Kohl deserves to be remembered and mourned.","translation":"正是这种不可或缺的政治家的品质，而不仅仅是因为带来了德国的重新统一，让科尔值得被铭记和哀悼。","targetForm":"deserves","senseId":"source-v-2","sourceSenseId":"v-2"}]},"denial":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"否认"}],"examples":[{"sentence":"Populism rests on a toxic triad: denial of complexity, anti-pluralism, and a crooked version of representation.","translation":"民粹主义的基础是有毒三元组：否定复杂性、反多元主义和扭曲代表形式。","targetForm":"denial","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In its more extreme variants, cis ideology can include denial of the empirical reality of intersex and transgender people.","translation":"在更极端的变体中，顺性别意识形态可能包括否认阴阳人和跨性别者的现实经历。","targetForm":"denial","senseId":"source-n-1","sourceSenseId":"n-1"}]},"deteriorate":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"(使)恶化"}],"examples":[{"sentence":"The main question about economic policy in Putin’s third term, then, is how fast it will deteriorate.","translation":"因此，普京的第三个任期在经济政策上最主要的问题是它将以多快的速度恶化。","targetForm":"deteriorate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"If Tom doesn't take the prescribed medicine, his state of health might deteriorate.","translation":"如果汤姆不服用处方药，他的健康状况可能会恶化。","targetForm":"deteriorate","senseId":"source-v-1","sourceSenseId":"v-1"}]},"dear":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"亲爱的人"}],"examples":[{"sentence":"Dear Germany: Sorry that Trump has repeatedly insulted Chancellor Angela Merkel.","translation":"亲爱的德国：对不起，特朗普 多次攻击你们的总理默克尔。","targetForm":"dear","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Dear Africa: We apologize for Trump’s obscene remarks insulting your countries in January.","translation":"亲爱的非洲：我们为特朗普1月份冒犯你们的国家的猥琐言论致歉。","targetForm":"dear","senseId":"source-n-1","sourceSenseId":"n-1"}]},"despair":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"绝望"}],"examples":[{"sentence":"She watched in despair as the thief stomped on her garden plants.","translation":"她绝望地看着小偷践踏她花园里的植物。","targetForm":"despair","senseId":"source-n-1","sourceSenseId":"n-1"}]},"democratic":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"民主的"}],"examples":[{"sentence":"Europe deserves to prove that it is a real community, one diverse, democratic, spiritual, free, and prosperous.","translation":"欧洲应该证明自己是一个真正的社会，一个多元、民主、高尚、自由和繁荣的社会。","targetForm":"democratic","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"These trends can be reversed, but only if we agree on the causes of democratic backsliding and target our solutions accordingly.","translation":"这些趋势是可以扭转的，但条件是我们必须在民主滑坡的原因上取得一致，并据此校准解决方案。","targetForm":"democratic","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"defend":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"防护"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"辩护"}],"examples":[{"sentence":"The trees help defend the riverbank against erosion during periods of unusually heavy rain.","translation":"在异常强降雨期间，树木有助于保护河岸免受侵蚀。","targetForm":"defend","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The lawyer defended the proposal by showing that it would reduce costs without removing essential services.","translation":"律师通过说明提案能在不取消必要服务的情况下减少成本，为其辩护。","targetForm":"defended","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Students should be prepared to defend their conclusions with evidence rather than personal preference.","translation":"学生应准备好用证据而非个人偏好为自己的结论辩护。","targetForm":"defend","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The new wall was designed to defend homes from water when the nearby stream rises quickly.","translation":"这面新墙旨在保护住宅免受附近溪流迅速上涨的水侵害。","targetForm":"defend","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"She defended her decision calmly after the committee asked why the schedule had been changed.","translation":"委员会询问为何改变时间表后，她冷静地为自己的决定辩护。","targetForm":"defended","senseId":"source-v-2","sourceSenseId":"v-2"}]},"derive":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"起源"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"得自"}],"examples":[{"sentence":"Superstitions derive from the inability of men to acknowledge that coincidences are merely coincidences.","translation":"迷信之所以存在，是因为人无法接受巧合只是巧合而已。","targetForm":"derive","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"From reading good books we can derive pleasure, friendship, experience and instruction.","translation":"读书，可以获得乐趣、友谊、经验和指导。","targetForm":"derive","senseId":"source-v-1","sourceSenseId":"v-1"}]},"descendant":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"后裔"}],"examples":[{"sentence":"BERKELEY – On July 10, one very important descendant of black Africa will make a triumphant return to the motherland.","translation":"伯克利 — — 7月10日，黑色非洲的一位非常重要的后裔将会荣归故里。","targetForm":"descendant","senseId":"source-n-1","sourceSenseId":"n-1"}]},"declare":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"宣布"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"声明"}],"examples":[{"sentence":"Declaring war after a surprise attack is to be expected, but killing over ten thousand non-combatants with a bomb is something unheard of.","translation":"被突袭后宣告战争是可以预想的，但用炸弹屠杀万人以上的平民却是前所未闻的。","targetForm":"declaring","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The court declared him innocent on the charge of murder.","translation":"法庭对他的谋杀罪名作出了无罪判决。","targetForm":"declared","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Tom is suspicious of Mary even though he declares otherwise.","translation":"汤姆虽然说了一套，但依然怀疑玛丽。","targetForm":"declares","senseId":"source-v-2","sourceSenseId":"v-2"}]},"detect":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"探测"}],"examples":[{"sentence":"Instead, they detect sounds through their tongues and feel vibrations through sense organs in the skull.","translation":"相反，他们通过舌头来侦测声音，并通过头骨内的感觉器官来感受震动。","targetForm":"detect","senseId":"source-v-3","sourceSenseId":"v-3"}]},"decide":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"决定"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"判决"}],"examples":[{"sentence":"The committee will decide whether to extend the pilot after reviewing feedback from students and staff.","translation":"委员会审阅学生和员工反馈后，将决定是否延长试点。","targetForm":"decide","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"She decided to take the earlier train because the weather forecast warned of heavy rain later.","translation":"天气预报警告稍后有大雨，因此她决定乘坐更早的火车。","targetForm":"decided","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"A judge must decide the case on the evidence presented rather than on public opinion.","translation":"法官必须根据提交的证据而非公众意见裁决案件。","targetForm":"decide","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Students should not decide too quickly when two sources appear to offer conflicting explanations.","translation":"当两个来源似乎给出相互冲突的解释时，学生不应过快下结论。","targetForm":"decide","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The final result was decided by one careful measurement taken after all the equipment had been checked.","translation":"所有设备核查后进行的一次仔细测量决定了最终结果。","targetForm":"decided","senseId":"source-v-1","sourceSenseId":"v-1"}]},"delicious":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"美味的"}],"examples":[{"sentence":"This farm's free-range eggs have a deeper shell color, and the yolks are especially rich and delicious.","translation":"这家农场的草鸡蛋颜色偏深，蛋黄特别鲜美。","targetForm":"delicious","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The free-range eggs from this farm are darker in color, and the yolks are extraordinarily delicious.","translation":"这家农场的草鸡蛋颜色偏深，蛋黄特别鲜美。","targetForm":"delicious","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"David decided to sneak into the kitchen and find something delicious to eat.","translation":"大卫决定偷偷溜进厨房，找点好吃的吃。","targetForm":"delicious","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The dishes were not so delicious, but otherwise the party was a success.","translation":"虽然食物不怎么好吃，但是派对在其它方面办得很出色。","targetForm":"delicious","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"deck":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"甲板"}],"examples":[{"sentence":"Memorizing the order of a deck of playing cards is definitely not easy, but it's not impossible.","translation":"把一叠扑克牌的排列次序背熟，虽然绝不是一件易事，却也不是没有可能的。","targetForm":"deck","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Memorising the cards in a deck in order is certainly a difficult task, but manageable.","translation":"把一叠扑克牌的排列次序背熟，虽然绝不是一件易事，却也不是没有可能的。","targetForm":"deck","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"She stood on the deck with her long hair waving in the wind.","translation":"她站在甲板上，长头发随风飞舞。","targetForm":"deck","senseId":"source-n-1","sourceSenseId":"n-1"}]},"desperate":{"senseGroups":[{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"极渴望的"}],"examples":[{"sentence":"The jobless became desperate for work – any work that would help them to support their families.","translation":"失业者渴望工作——任何有助于养家糊口的工作都可以。","targetForm":"desperate","senseId":"source-adj-4","sourceSenseId":"adj-4"}]},"detach":{"senseGroups":[{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"分离","contextReviewed":true}],"examples":[{"sentence":"The beautiful red leaves of the maple become detached from the branches and are dancing in the wind.","translation":"枫树美丽的红叶从枝头飘落，在风中翩翩起舞。","targetForm":"detached","senseId":"source-v-4","sourceSenseId":"v-4"}]},"desk":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"办公桌"}],"examples":[{"sentence":"After asking for my key at the front desk, I took the elevator to my floor.","translation":"我到柜台拿了钥匙，然后就乘电梯去了我房间的楼层。","targetForm":"desk","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"I am going to enquire at the service desk if there are any restaurants around here.","translation":"我要去柜台打听这里附近有没有餐厅。","targetForm":"desk","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"I noticed a note on my desk, but I do not know who wrote it.","translation":"我发现了我办公桌上有张字条, 但是我不知道是谁写的。","targetForm":"desk","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"I only missed one day of work because of a cold and my desk is piled high with papers.","translation":"我才感冒一天没来上班，桌上就堆满了文件。","targetForm":"desk","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"She has asked the person at the front desk to connect her to that number.","translation":"她请了前台的人为她打那个号码。","targetForm":"desk","senseId":"source-n-2","sourceSenseId":"n-2"}]},"description":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"描述"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"说明"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"种类"}],"examples":[{"sentence":"Her description of the old market helped the designer understand which details local residents valued most.","translation":"她对旧市场的描述帮助设计师了解当地居民最珍视哪些细节。","targetForm":"description","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The job description makes clear that applicants must be able to communicate with people from different backgrounds.","translation":"职位说明明确指出，申请人必须能够与不同背景的人沟通。","targetForm":"description","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"A brief description of the method allows other researchers to understand how the data were collected.","translation":"对方法的简短说明使其他研究人员能理解数据如何收集。","targetForm":"description","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The catalogue groups items by description so that customers can find the type of material they need.","translation":"目录按品类说明归类物品，使顾客能找到所需材料类型。","targetForm":"description","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Clear descriptions of each service helped visitors decide which office could answer their questions.","translation":"每项服务的清晰说明帮助访客决定哪个办公室能回答他们的问题。","targetForm":"descriptions","senseId":"source-n-2","sourceSenseId":"n-2"}]},"detective":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"侦探"}],"examples":[{"sentence":"She employed a private detective to keep a watch on her husband.","translation":"她雇了一个私人侦探看守她的丈夫。","targetForm":"detective","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Father would often read detective stories in his spare time.","translation":"父亲常常在空闲时间读侦探小说。","targetForm":"detective","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Private detectives were hired to look into the strange case.","translation":"私家侦探们受雇调查这桩奇怪的案件。","targetForm":"detectives","senseId":"source-n-1","sourceSenseId":"n-1"}]},"deprive":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"使丧失"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"剥夺"}],"examples":[{"sentence":"Closing the only bus route would deprive some residents of access to work and medical care.","translation":"关闭唯一公交线路会使一些居民失去获得工作和医疗服务的机会。","targetForm":"deprive","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Poor lighting can deprive students of a comfortable place to read during the darker months.","translation":"照明不良会使学生在较暗月份失去舒适阅读场所。","targetForm":"deprive","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The flood deprived several families of safe access to their homes until the bridge was repaired.","translation":"洪水使几户家庭在桥梁修复前无法安全到达家中。","targetForm":"deprived","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"A policy should not deprive people of information they need to understand a decision that affects them.","translation":"政策不应剥夺人们理解影响自身决定所需的信息。","targetForm":"deprive","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The roadworks temporarily deprived the shop of deliveries, so staff arranged collection from a nearby depot.","translation":"道路施工暂时使商店无法收货，因此员工安排从附近仓库自取。","targetForm":"deprived","senseId":"source-v-2","sourceSenseId":"v-2"}]},"deal":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"买卖"}],"examples":[{"sentence":"I mean, of course, the regime in Damascus, which years ago we should have begun to deal with as we dealt with Muammar el-Qaddafi’s regime.","translation":"当然，我指的是大马士革政权，多年前我们就应该像对待卡扎菲政权那样处理它。","targetForm":"deal","senseId":"source-n-4","sourceSenseId":"n-4"}]},"despise":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"轻视"}],"examples":[{"sentence":"The most enlightened way of living is to despise social conventions while at the same time living your life in conformity to them.","translation":"最光明的处世方法是既蔑视社会的因袭，又过着与社会的因袭不相矛盾的生活。","targetForm":"despise","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Practice is as important as theory, but we are apt to value the latter and despise the former.","translation":"实践和理论同样重要，但我们倾向于重视后者而忽略前者。","targetForm":"despise","senseId":"source-v-1","sourceSenseId":"v-1"}]},"depend":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"靠"}],"examples":[{"sentence":"Corporations and the military depend on assessment and sorting devices that are little more than disguised intelligence tests.","translation":"也许必须对智力给予一些关注，然而忽略起码是同样重要的认知能力—这一趋势却不合理：正是这种能力支撑起理性的思维和行为。","targetForm":"depend","senseId":"source-v-1","sourceSenseId":"v-1"}]}}};
